create or replace function public.has_permission_for_user(p_user_id uuid,p_organization_id uuid,p_permission_code text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_memberships om join public.role_permissions rp on rp.role=om.role where om.organization_id=p_organization_id and om.user_id=p_user_id and om.status='active' and rp.permission_code=p_permission_code); $$; revoke all on function public.has_permission_for_user(uuid,uuid,text) from public; revoke all on function public.has_permission_for_user(uuid,uuid,text) from anon; revoke all on function public.has_permission_for_user(uuid,uuid,text) from authenticated; grant execute on function public.has_permission_for_user(uuid,uuid,text) to service_role;